1	<?php
2	// Sembrado reproducible e idempotente del entorno. Solo datos sintéticos.
3	//   - Curso QA101, profesor y 6 estudiantes con nombres fijos (estables para el QA visual).
4	//   - Banco de preguntas del curso con 3 categorías = 3 temas (spec 3).
5	//   - Preguntas: opción múltiple, verdadero/falso y ensayo (regresión del camino feliz).
6	//   - "Examen de regresión" con retroalimentación global configurada (escenario 2 del spec 3).
7	// Uso: php /opt/seed/seed.php   (como www-data, dentro del contenedor web)
8	define('CLI_SCRIPT', true);
9	require('/var/www/moodle/config.php');
10	require_once($CFG->libdir . '/testing/generator/lib.php');
11	require_once($CFG->dirroot . '/mod/quiz/locallib.php');
12	
13	use core_question\local\bank\question_bank_helper;
14	
15	global $DB;
16	\core\session\manager::set_user(get_admin());
17	
18	if ($DB->record_exists('course_modules', ['idnumber' => 'QUIZ-REG'])) {
19	    echo "Ya sembrado (examen QUIZ-REG existe). Nada que hacer.\n";
20	    exit(0);
21	}
22	if ($DB->record_exists('course', ['shortname' => 'QA101'])) {
23	    fwrite(STDERR, "Sembrado parcial detectado (curso sin examen). Ejecutar: ./entorno/setup.sh --fresh\n");
24	    exit(1);
25	}
26	
27	$gen = new testing_data_generator();
28	const PASS = 'Viaro.2026';
29	
30	$course = $gen->create_course(['fullname' => 'Curso QA de Exámenes', 'shortname' => 'QA101', 'idnumber' => 'QA101']);
31	
32	$mkuser = function (string $username, string $first, string $last) use ($gen) {
33	    return $gen->create_user([
34	        'username' => $username, 'password' => PASS, 'firstname' => $first, 'lastname' => $last,
35	        'email' => "{$username}@example.invalid", 'idnumber' => strtoupper($username),
36	    ]);
37	};
38	$profesor = $mkuser('profesor', 'Paula', 'Profesora');
39	$gen->enrol_user($profesor->id, $course->id, 'editingteacher');
40	// 12 estudiantes: cada spec usa un rango propio para que sus pruebas no compartan intentos (ver conocimiento).
41	for ($i = 1; $i <= 12; $i++) {
42	    $u = $mkuser("estudiante{$i}", 'Estudiante', "Número {$i}");
43	    $gen->enrol_user($u->id, $course->id, 'student');
44	}
45	
46	// Banco de preguntas del curso (Moodle 5.x: los bancos son instancias de mod_qbank).
47	$qbank = question_bank_helper::get_default_open_instance_system_type($course, true);
48	$bankctx = context_module::instance($qbank->id);
49	$qgen = $gen->get_plugin_generator('core_question');
50	
51	$temas = ['ALG' => 'Álgebra', 'GEO' => 'Geometría', 'HIS' => 'Historia'];
52	$cats = [];
53	foreach ($temas as $code => $name) {
54	    $cats[$code] = $qgen->create_question_category(['contextid' => $bankctx->id, 'name' => $name, 'idnumber' => "TEMA-{$code}"]);
55	}
56	
57	// Determinismo: sin mezclar opciones (la mezcla aleatoria rompe cualquier comparación visual y
58	// vuelve ambiguos los selectores). Se fija en la pregunta Y en el quiz.
59	$q = [];
60	$q[] = $qgen->create_question('multichoice', 'one_of_four', ['category' => $cats['ALG']->id, 'name' => 'ALG-1 Opción múltiple', 'shuffleanswers' => 0]);
61	$q[] = $qgen->create_question('truefalse', 'true', ['category' => $cats['ALG']->id, 'name' => 'ALG-2 Verdadero o falso']);
62	$q[] = $qgen->create_question('multichoice', 'one_of_four', ['category' => $cats['GEO']->id, 'name' => 'GEO-1 Opción múltiple', 'shuffleanswers' => 0]);
63	$q[] = $qgen->create_question('truefalse', 'true', ['category' => $cats['GEO']->id, 'name' => 'GEO-2 Verdadero o falso']);
64	$q[] = $qgen->create_question('truefalse', 'true', ['category' => $cats['HIS']->id, 'name' => 'HIS-1 Verdadero o falso']);
65	$q[] = $qgen->create_question('essay', 'editor', ['category' => $cats['HIS']->id, 'name' => 'HIS-2 Ensayo']);
66	
67	$quizgen = $gen->get_plugin_generator('mod_quiz');
68	$quiz = $quizgen->create_instance([
69	    'course' => $course->id, 'name' => 'Examen de regresión', 'idnumber' => 'QUIZ-REG',
70	    'intro' => 'Examen sembrado para la regresión del camino feliz.',
71	    'questionsperpage' => 2, 'grade' => 10, 'sumgrades' => 0, 'attempts' => 0, 'shuffleanswers' => 0,
72	    'preferredbehaviour' => 'deferredfeedback',
73	    'overallfeedbacks' => [
74	        ['mingrade' => '50%', 'maxgrade' => '101%', 'feedbacktext' => 'Retro global: aprobado.'],
75	        ['mingrade' => '0%', 'maxgrade' => '50%', 'feedbacktext' => 'Retro global: necesitas repasar.'],
76	    ],
77	]);
78	foreach ($q as $i => $question) {
79	    quiz_add_quiz_question($question->id, $quiz, intdiv($i, 2) + 1);
80	}
81	// En 5.x quiz_update_sumgrades() ya no existe: se usa el grade_calculator.
82	\mod_quiz\quiz_settings::create($quiz->id)->get_grade_calculator()->recompute_quiz_sumgrades();
83	
84	echo "Sembrado OK\n";
85	echo "  curso QA101 id={$course->id}\n  quiz QUIZ-REG id={$quiz->id} cmid={$quiz->cmid}\n";
86	echo "  usuarios: admin, profesor, estudiante1..12 (clave " . PASS . ")\n";
87

