1	#!/usr/bin/env node
2	// Fábrica: un comando por spec.
3	//   node factory/cli.mjs run specs/spec-1-reconocimiento.md      pipeline completo -> rama + PR (sin merge)
4	//   node factory/cli.mjs suite                                   suite completa funcional + visual + honestidad
5	//   node factory/cli.mjs honestidad                              solo el control de verificación honesta
6	//   node factory/cli.mjs aprobar-linea-base <png|--pendientes> --razon "..."   (HUMANO)
7	//   node factory/cli.mjs aprobar-pruebas --razon "..."                          (HUMANO)
8	import fs from 'node:fs';
9	import path from 'node:path';
10	import { RAIZ, Corrida, sh, shOk, escribir, leer, existe, archivos } from './lib/util.mjs';
11	import { llamarIA, extraerJSON } from './lib/ia.mjs';
12	import * as moodle from './lib/moodle.mjs';
13	import { correrPruebas, resumen, contextoFallos } from './lib/pruebas.mjs';
14	import { verificar, informe, construirManifiesto } from './honestidad/verificar.mjs';
15	import { generarTrazabilidad } from './lib/trazabilidad.mjs';
16	import { lineasBaseNuevas, registrarPendientes, proponerLineasBase, aprobarLineaBase } from './lib/lineas-base.mjs';
17	
18	const MAX_REINTENTOS = Number(process.env.FACTORY_REINTENTOS || 3);
19	const [, , comando, ...resto] = process.argv;
20	const opt = (n) => { const i = resto.indexOf(n); return i >= 0 ? resto[i + 1] : null; };
21	
22	const comandos = { run, suite, honestidad, 'aprobar-linea-base': aprobarLB, 'aprobar-pruebas': aprobarPruebas };
23	if (!comandos[comando]) { console.error(`Uso: node factory/cli.mjs <${Object.keys(comandos).join('|')}> ...`); process.exit(2); }
24	try { process.exitCode = await comandos[comando](); } catch (e) { console.error(e.stack || e); process.exitCode = 1; }
25	
26	// ---------------------------------------------------------------------------------------------------------
27	async function run() {
28	  const specPath = resto.find((a) => !a.startsWith('--'));
29	  if (!specPath || !existe(specPath)) throw new Error(`Spec no encontrado: ${specPath}`);
30	  const specTxt = leer(specPath);
31	  const specId = (specTxt.match(/^id:\s*(\S+)/m) || [])[1] || path.basename(specPath, '.md');
32	  const specDir = `salidas/${specId}`;
33	  const c = new Corrida(specId);
34	  const rama = `factory/${specId}-${c.id.slice(0, 15)}`;
35	  c.log('inicio', `Spec ${specPath} (${specId}). Corrida ${c.dir}. Rama ${rama}.`);
36	
37	  // 0. Precondiciones
38	  if (!moodle.moodleArriba()) return falla(c, 'precondicion', 'Moodle no responde en http://localhost:8090. Ejecutar: bash entorno/setup.sh');
39	  // La carpeta de esta misma corrida ya existe (es donde se escribe el log): no cuenta como cambio.
40	  const sucio = sh('git status --porcelain').out.split('\n').filter((l) => l && !l.slice(3).startsWith('corridas/')).join('\n');
41	  if (sucio) return falla(c, 'precondicion', 'El árbol de trabajo tiene cambios sin commit. La fábrica parte de un estado limpio.', sucio);
42	  shOk(`git checkout -q -b ${rama}`);
43	  fs.rmSync(path.join(RAIZ, specDir), { recursive: true, force: true });
44	  escribir(`${specDir}/spec.md`, specTxt);
45	
46	  // 1. Análisis: plan, capa, bordes, criterios -> pruebas
47	  let plan = null;
48	  let feedback = '';
49	  for (let i = 1; i <= 3 && !plan; i++) {
50	    const lineas_base = fs.readdirSync(path.join(RAIZ, 'visual/lineas-base')).filter((f) => f.endsWith('.png')).join(', ') || '(ninguna todavía)';
51	    const r = llamarIA(c, { rol: 'analista', plantilla: 'analista', vars: { spec: specTxt, spec_id: specId, conocimiento: leer('factory/conocimiento/moodle-5.3.md'), helpers: leer('factory/regresion/helpers.ts'), feedback, lineas_base } });
52	    try {
53	      plan = validarPlan(extraerJSON(r.texto), specId);
54	      c.log('analisis', `Plan válido en intento ${i}: capa ${plan.componente || '(solo pruebas)'} — ${plan.criterios.length} criterios, ${plan.bordes.length} bordes.`);
55	    } catch (e) {
56	      feedback = `Tu respuesta anterior no es un plan válido: ${e.message}. Devolvé SOLO el bloque \`\`\`json con el esquema pedido.`;
57	      c.log('analisis', `Plan inválido (intento ${i}), se reintenta.`, e.message);
58	    }
59	  }
60	  if (!plan) return falla(c, 'analisis', 'La IA no produjo un plan válido en 3 intentos.');
61	  escribir(`${specDir}/plan.json`, JSON.stringify(plan, null, 2));
62	
63	  // 2. Sondas: verificar contra la realidad antes de construir (contratos externos, comportamiento actual)
64	  const sondas = ejecutarSondas(c, plan.sondas || []);
65	  escribir(`${specDir}/sondas.json`, JSON.stringify(sondas, null, 2));
66	
67	  // 3. Implementación (código + pruebas)
68	  const varsImpl = { spec: specTxt, spec_id: specId, plan, sondas, conocimiento: leer('factory/conocimiento/moodle-5.3.md'), helpers: leer('factory/regresion/helpers.ts'), spec_dir: specDir };
69	  llamarIA(c, { rol: 'implementador', plantilla: 'implementador', vars: varsImpl, escritura: specDir });
70	
71	  // 4. Bucle validar -> desplegar -> probar -> corregir
72	  let verde = false;
73	  let res = null;
74	  for (let intento = 1; intento <= MAX_REINTENTOS + 1; intento++) {
75	    const problemas = validacionesEstaticas(c, specDir, plan);
76	    let detalle = problemas.join('\n');
77	    if (!problemas.length) {
78	      const d = moodle.desplegar(specDir);
79	      c.log('despliegue', `Plugins: ${d.plugins.map((p) => p.componente).join(', ') || '(ninguno)'} — upgrade ${d.ok ? 'OK' : 'FALLÓ'}`, d.ok ? null : d.salida);
80	      if (!d.ok) detalle = `La actualización de Moodle falló:\n${d.salida}`;
81	      else {
82	        moodle.reset();
83	        const pruebasSpec = archivos(`${specDir}/pruebas`, (f) => f.endsWith('.spec.ts'));
84	        res = correrPruebas(pruebasSpec, c.ruta('spec'), { crearLineasBaseFaltantes: true });
85	        const s = resumen(res.resultados);
86	        c.log('pruebas', `Intento ${intento}: ${s.passed} OK, ${s.failed} fallidas, ${s.skipped} omitidas.`, s.failed ? contextoFallos(c.ruta('spec'), res.resultados) : null);
87	        if (s.failed === 0 && s.passed > 0) { verde = true; break; }
88	        detalle = s.passed + s.failed === 0 ? `No se ejecutó ninguna prueba.\n${res.salida.slice(-3000)}` : contextoFallos(c.ruta('spec'), res.resultados);
89	      }
90	    }
91	    if (intento > MAX_REINTENTOS) break;
92	    c.log('reintento', `Intento ${intento} no quedó verde. Se le pide a la IA que corrija (${intento}/${MAX_REINTENTOS}).`);
93	    llamarIA(c, { rol: 'corrector', plantilla: 'corrector', vars: { ...varsImpl, problemas: detalle, intento: String(intento) }, escritura: specDir });
94	  }
95	  if (!verde) return falla(c, 'pruebas', `Las pruebas del spec no quedaron en verde tras ${MAX_REINTENTOS} reintentos. Se detiene sin PR; la rama ${rama} queda para diagnóstico.`);
96	
97	  // 5. Mutación "sin la funcionalidad": las pruebas @requiere-feature deben fallar sin el plugin
98	  let sinFeature = null;
99	  if (moodle.pluginsDe(specDir).length) {
100	    const r = moodle.retirar(specDir);
101	    c.log('mutacion', `Plugin retirado para probar que las pruebas detectan su ausencia (${r.ok ? 'OK' : 'con avisos'}).`);
102	    moodle.reset();
103	    const pruebasSpec = archivos(`${specDir}/pruebas`, (f) => f.endsWith('.spec.ts'));
104	    sinFeature = correrPruebas(pruebasSpec, c.ruta('sin-feature'), { grep: '@requiere-feature' }).resultados;
105	    const s = resumen(sinFeature);
106	    c.log('mutacion', `Sin la funcionalidad: ${s.failed} fallan (esperado), ${s.passed} pasan (cada una es un hallazgo).`);
107	    moodle.desplegar(specDir);
108	  }
109	
110	  // 6. Regresión completa (nada de lo existente se rompió) + líneas base nuevas
111	  moodle.reset();
112	  let total = correrPruebas([], c.dir, { crearLineasBaseFaltantes: false });
113	  // Pantallas que el spec declara cambiar A PROPÓSITO: la imagen obtenida se PROPONE como nueva línea base,
114	  // pendiente de aprobación humana en el PR. Diferencias en pantallas NO declaradas siguen siendo fallos.
115	  const propuestas = proponerCambiosVisuales(c, plan, total.resultados);
116	  if (propuestas.length) {
117	    c.log('visual', `Cambios visuales declarados por el plan (${plan.pantallas_afectadas.join(', ')}): se proponen ${propuestas.length} líneas base, pendientes de aprobación humana.`, propuestas.join('\n'));
118	    copiarDiferencias(c);
119	    moodle.reset();
120	    total = correrPruebas([], c.dir, { crearLineasBaseFaltantes: false });
121	  }
122	  const st = resumen(total.resultados);
123	  c.log('regresion', `Suite completa: ${st.passed} OK, ${st.failed} fallidas, ${st.skipped} omitidas.`, st.failed ? contextoFallos(c.dir, total.resultados) : null);
124	  const nuevas = lineasBaseNuevas();
125	  if (nuevas.length) { registrarPendientes(nuevas, specId); c.log('visual', `Líneas base NUEVAS (pantallas que introduce el spec), pendientes de aprobación humana en el PR: ${nuevas.join(', ')}`); }
126	
127	  // 7. Alcance: la IA solo pudo cambiar salidas/<spec>/ y líneas base nuevas; el core de Moodle intacto
128	  const fuera = sh('git status --porcelain').out.split('\n').filter(Boolean).map((l) => l.slice(3))
129	    .filter((f) => !f.startsWith(specDir) && !f.startsWith('corridas/') && !f.startsWith('ia/transcripciones/') && !f.startsWith('visual/lineas-base/') && !f.startsWith('test-results'));
130	  const core = moodle.verificarCoreIntacto(rutasPluginsDesplegados());
131	  if (fuera.length || core.length) return falla(c, 'alcance', 'Cambios fuera del alcance permitido.', [...fuera.map((f) => `repo: ${f}`), ...core.map((x) => `core moodle: ${x}`)].join('\n'));
132	  c.log('alcance', 'Solo cambió salidas/ del spec; core de Moodle intacto (git status del árbol de Moodle).');
133	
134	  // 8. Control de verificación honesta (independiente). Bloquea.
135	  const H = verificar({ resultados: total.resultados, sinFeature, plan });
136	  const txtH = informe(H);
137	  escribir(c.ruta('honestidad.log'), txtH);
138	  c.log('honestidad', H.length ? `BLOQUEADO con ${H.length} hallazgo(s).` : 'OK.', txtH);
139	  if (H.length) return falla(c, 'honestidad', 'El control de verificación honesta bloqueó la corrida. No se abre PR.');
140	  if (st.failed) return falla(c, 'regresion', 'La regresión completa tiene fallos. No se abre PR.');
141	
142	  // 9. Evidencia, trazabilidad, diff, commit, PR (sin merge)
143	  generarTrazabilidad({ plan, specDir, resultados: total.resultados, corrida: c });
144	  shOk(`git add -A ${specDir} visual/lineas-base`);
145	  const diff = sh(`git diff --cached -- ${specDir}/codigo visual/lineas-base`).out;
146	  escribir(`${specDir}/cambios.diff`, diff || '(sin cambios de código: spec de solo pruebas)\n');
147	  shOk(`git add -A ${specDir} ${c.dir} ia/transcripciones visual/lineas-base`);
148	  shOk(`git commit -q -m "feat(${specId}): ${plan.titulo}" -m "Generado por la fábrica. Corrida ${c.dir}."`);
149	  const pr = abrirPR(c, rama, plan, specDir, st, txtH, nuevas);
150	  c.log('fin', `PR propuesto: ${pr}. El pipeline se detiene en aprobación humana: no mergea ni despliega.`);
151	  sh(`git add -A ${c.dir} && git commit -q -m "chore(${specId}): log final de la corrida" && git push -q origin ${rama}`);
152	  shOk('git checkout -q main');
153	  return 0;
154	}
155	
156	function proponerCambiosVisuales(c, plan, resultados) {
157	  const afectadas = plan.pantallas_afectadas || [];
158	  if (!afectadas.length) return [];
159	  const art = path.join(RAIZ, c.dir, 'artefactos');
160	  if (!fs.existsSync(art)) return [];
161	  const hechas = [];
162	  for (const f of fs.readdirSync(art, { recursive: true }).filter((x) => x.endsWith('-actual.png'))) {
163	    // Playwright nombra el artefacto <nombre-captura>-actual.png; la línea base es <nombre>--<proyecto>.png
164	    const nombre = path.basename(f).replace(/-actual\.png$/, '');
165	    const proyecto = /-movil$/.test(path.dirname(f)) ? 'movil' : 'escritorio';
166	    if (!afectadas.some((p) => nombre.startsWith(p))) continue;
167	    const destino = `visual/lineas-base/${nombre}--${proyecto}.png`;
168	    if (!fs.existsSync(path.join(RAIZ, destino))) continue;
169	    fs.copyFileSync(path.join(art, f), path.join(RAIZ, destino));
170	    hechas.push(destino);
171	  }
172	  if (hechas.length) proponerLineasBase(hechas.map((h) => path.basename(h)), plan.spec_id);
173	  void resultados;
174	  return hechas;
175	}
176	
177	function falla(c, etapa, msg, detalle) {
178	  c.log(etapa, `DETENIDO: ${msg}`, detalle);
179	  return 1;
180	}
181	
182	function validarPlan(p, specId) {
183	  const req = ['spec_id', 'titulo', 'naturaleza', 'capa_justificacion', 'criterios', 'bordes'];
184	  for (const k of req) if (p[k] === undefined) throw new Error(`falta "${k}"`);
185	  if (p.spec_id !== specId) throw new Error(`spec_id debe ser "${specId}"`);
186	  if (!Array.isArray(p.criterios) || !p.criterios.length) throw new Error('criterios vacío');
187	  for (const ca of p.criterios) if (!ca.id || !ca.texto || !ca.verificacion) throw new Error(`criterio incompleto: ${JSON.stringify(ca)}`);
188	  if (p.componente && !/^(quizaccess|local|quiz|block|qbank|qtype|qbehaviour|report|tool|theme)_[a-z0-9_]+$/.test(p.componente)) throw new Error(`componente inválido: ${p.componente}`);
189	  if (p.componente && !/^public\//.test(p.ruta_moodle || '')) throw new Error('ruta_moodle debe empezar con public/ (Moodle >= 5.1)');
190	  return p;
191	}
192	
193	function ejecutarSondas(c, sondas) {
194	  const out = [];
195	  for (const s of sondas.slice(0, 8)) {
196	    const body = s.body !== undefined ? `-H 'Content-Type: application/json' --data '${JSON.stringify(s.body).replace(/'/g, "'\\''")}'` : '';
197	    const r = sh(`curl -s -m 15 -X ${s.metodo || 'GET'} ${body} -w '\\n__HTTP__%{http_code}' '${s.url}'`);
198	    const [cuerpo, code] = r.out.split('\n__HTTP__');
199	    out.push({ ...s, respuesta: { http: Number(code), cuerpo: cuerpo.slice(0, 4000) } });
200	    c.log('sonda', `${s.metodo || 'GET'} ${s.url} -> HTTP ${code}`, `${s.descripcion || ''}\n${cuerpo.slice(0, 1500)}`);
201	  }
202	  return out;
203	}
204	
205	function validacionesEstaticas(c, specDir, plan) {
206	  const p = [];
207	  const plugins = moodle.pluginsDe(specDir);
208	  if (plan.componente) {
209	    const esperado = plugins.find((x) => x.componente === plan.componente);
210	    if (!esperado) p.push(`No existe ${specDir}/codigo/${plan.ruta_moodle}/version.php con $plugin->component = '${plan.componente}'.`);
211	    else if (esperado.rel !== plan.ruta_moodle) p.push(`El plugin está en ${esperado.rel} pero el plan dice ${plan.ruta_moodle}.`);
212	  }
213	  p.push(...moodle.lintPHP(specDir).map((x) => `Error de sintaxis PHP: ${x}`));
214	  const pruebas = archivos(`${specDir}/pruebas`, (f) => f.endsWith('.spec.ts'));
215	  if (!pruebas.length) p.push(`No hay pruebas en ${specDir}/pruebas/*.spec.ts`);
216	  const textoPruebas = pruebas.map((f) => leer(f)).join('\n');
217	  for (const ca of plan.criterios) {
218	    if (ca.verificacion === 'proceso') continue;
219	    if (!textoPruebas.includes(`[${ca.id}]`)) p.push(`Ninguna prueba cubre ${ca.id} (el título debe incluir "[${ca.id}]").`);
220	  }
221	  c.log('validacion', p.length ? `${p.length} problema(s) estáticos.` : 'Validaciones estáticas OK (estructura, sintaxis PHP, cobertura de criterios).', p.join('\n') || null);
222	  return p;
223	}
224	
225	function rutasPluginsDesplegados() {
226	  return fs.readdirSync(path.join(RAIZ, 'salidas')).flatMap((s) => moodle.pluginsDe(`salidas/${s}`).map((p) => p.rel));
227	}
228	
229	function abrirPR(c, rama, plan, specDir, st, txtH, nuevas) {
230	  const cuerpo = `## ${plan.titulo}\n\nPropuesto por la fábrica a partir de \`${specDir}/spec.md\`. **El pipeline se detiene aquí: requiere aprobación humana. No mergea ni despliega.**\n\n`
231	    + `### Capa elegida\n\`${plan.componente || 'solo pruebas'}\` (${plan.ruta_moodle || '—'})\n\n${plan.capa_justificacion}\n\n`
232	    + `### Bordes del spec y criterio aplicado\n${plan.bordes.map((b) => `- **${b.descripcion}** → ${b.decision} _(${b.criterio})_`).join('\n')}\n\n`
233	    + `### Evidencia\n- Trazabilidad: \`${specDir}/trazabilidad.md\`\n- Diff: \`${specDir}/cambios.diff\`\n- Corrida: \`${c.dir}/\` (pipeline.log, funcional.xml, visual/, honestidad.log)\n`
234	    + `- Suite completa: ${st.passed} OK, ${st.failed} fallidas, ${st.skipped} omitidas\n\n`
235	    + (nuevas.length ? `### ⚠️ Líneas base visuales NUEVAS — revisar y aprobar\n${nuevas.map((n) => `- \`visual/lineas-base/${n}\``).join('\n')}\nAprobar con: \`node factory/cli.mjs aprobar-linea-base --pendientes --razon "..."\`\n\n` : '')
236	    + `### Control de verificación honesta\n\`\`\`\n${txtH}\`\`\`\n`;
237	  escribir(c.ruta('pr.md'), cuerpo);
238	  const push = sh(`git push -q -u origin ${rama}`);
239	  if (push.code !== 0) { c.log('pr', 'No se pudo hacer push (¿sin remoto/credenciales?). El PR queda descrito en pr.md.', push.err); return `(local) ${c.ruta('pr.md')}`; }
240	  const r = sh(`gh pr create --base main --head ${rama} --title "[${plan.spec_id}] ${plan.titulo}" --body-file ${c.ruta('pr.md')}`);

