33	  for (let i = desde; i < m.length; i++) {
34	    if (m[i] === '(' || m[i] === '{' || m[i] === '[') prof++;
35	    else if (m[i] === ')' || m[i] === '}' || m[i] === ']') { prof--; if (prof === 0) return i; }
