40	export function analizarArchivo(archivo, src) {
41	  const m = enmascarar(src);
42	  const pruebas = [];
43	  const re = /\b(test|it)(\.(only|skip|fixme|fail))?\s*\(\s*(['"`])/g;
44	  let x;
45	  while ((x = re.exec(m))) {
46	    const inicio = x.index;
