55	    const matchers = [...cuerpoM.matchAll(/\.\s*(not\s*\.\s*)?(to[A-Z]\w*)\s*\(/g)].map((y) => (y[1] ? 'not.' : '') + y[2]);
56	    pruebas.push({
57	      archivo, titulo, linea: linea(src, inicio),
58	      modificador: x[3] || null,
59	      asserts: (cuerpoM.match(/\bexpect\s*(\.\s*soft\s*)?\(/g) || []).length,
60	      soft: (cuerpoM.match(/\bexpect\s*\.\s*soft\s*\(/g) || []).length,
61	      matchers: matchers.sort(),
62	      fuertes: matchers.filter((k) => !MATCHERS_DEBILES.has(k.replace(/^not\./, ''))).length,
63	      capturas: (cuerpoM.match(/toHaveScreenshot\s*\(/g) || []).length,
64	      opcionesCaptura: [...cuerpo.matchAll(/(maxDiffPixels|maxDiffPixelRatio|threshold)\s*:\s*([\d.]+)/g)].map((y) => `${y[1]}=${y[2]}`),
