67	      // Aserciones web-first (asíncronas) sin await: la promesa queda flotando y la prueba nunca falla por ellas.
68	      sinAwait: [...cuerpoM.matchAll(/(await\s+)?expect\s*\([^;]*?\)\s*(\.\s*not)?\s*\.\s*(to(Have|BeVisible|BeHidden|BeEnabled|BeDisabled|BeChecked|BeEditable|BeEmpty|BeFocused|BeInViewport|BeAttached|ContainText|Pass)\w*)\s*\(/g)]
69	        .filter((y) => !y[1]).map((y) => y[3]),
70	      tragaErrores: /\.catch\s*\(\s*\(\s*\w*\s*\)\s*=>\s*(\{\s*\}|undefined|null|true|false)\s*\)|catch\s*(\(\s*\w*\s*\))?\s*\{\s*\}/.test(cuerpo),
71	      mockRed: /\b(route\.fulfill|page\.route|context\.route|routeFromHAR)\b/.test(cuerpoM),
72	      tags: [...titulo.matchAll(/(@[\w-]+|\[(CA-\d+|HUMO|REG-[\w-]+)\])/g)].map((y) => y[1]),
73	    });
74	  }
75	  // skip/fixme/only dinámicos o a nivel describe (dentro o fuera de pruebas)
76	  const omisiones = [...m.matchAll(/\b(test|describe|it)(\.describe)?\.(skip|fixme|only)\s*\(/g)].map((y) => ({ tipo: y[3], linea: linea(src, y.index), texto: src.slice(y.index, src.indexOf('\n', y.index)).trim() }));
77	  return { archivo, pruebas, omisiones };
78	}
