62	export function verificar({ resultados, sinFeature, plan } = {}) {
63	  const H = [];
64	  const hallazgo = (regla, donde, detalle) => H.push({ regla, donde, detalle });
65	  const ref = json(enRef(MANIFIESTO), null);
66	  const actual = construirManifiesto();
67	
68	  if (!ref) hallazgo('SIN-REFERENCIA', `${REF}:${MANIFIESTO}`, `No existe manifiesto aprobado en ${REF}. Sin referencia no se puede afirmar que nada se debilitó.`);
69	  const base = ref || { pruebas: {}, omisiones: {}, umbralVisual: actual.umbralVisual };
70	
71	  // 1) Pruebas aprobadas que desaparecieron o verifican menos que antes.
72	  for (const [id, a] of Object.entries(base.pruebas)) {
73	    const b = actual.pruebas[id];
74	    if (!b) { hallazgo('PRUEBA-ELIMINADA', id, 'Estaba en el manifiesto aprobado y ya no existe (¿renombrada o borrada?).'); continue; }
75	    if (b.asserts < a.asserts) hallazgo('ASSERTS-REDUCIDOS', id, `Tenía ${a.asserts} expect(), ahora ${b.asserts}.`);
76	    if (b.fuertes < a.fuertes) hallazgo('MATCHER-DEBILITADO', id, `Matchers fuertes: ${a.fuertes} -> ${b.fuertes}. Antes: [${a.matchers.join(', ')}] Ahora: [${b.matchers.join(', ')}]`);
77	    if (b.soft > a.soft) hallazgo('ASSERT-SOFT', id, `expect.soft no detiene la prueba: ${a.soft} -> ${b.soft}.`);
78	    if (b.capturas < a.capturas) hallazgo('CAPTURA-ELIMINADA', id, `Comparaciones visuales: ${a.capturas} -> ${b.capturas}.`);
79	    if (b.mascaras > a.mascaras) hallazgo('MASCARA-AGREGADA', id, `Máscaras en capturas: ${a.mascaras} -> ${b.mascaras}. Una máscara nueva puede tapar una rotura.`);
80	    if (JSON.stringify(b.opcionesCaptura) !== JSON.stringify(a.opcionesCaptura)) hallazgo('UMBRAL-POR-PRUEBA', id, `Opciones de tolerancia: [${a.opcionesCaptura}] -> [${b.opcionesCaptura}].`);
81	    if (b.modificador && b.modificador !== a.modificador) hallazgo('OMITIDA', id, `Ahora es test.${b.modificador}().`);
82	  }
83	
84	  // 2) Reglas que aplican a TODAS las pruebas (también a las nuevas que trae un spec).
85	  for (const f of listarPruebas()) {
86	    const a = analizarArchivo(f, fs.readFileSync(path.join(RAIZ, f), 'utf8'));
87	    for (const o of a.omisiones) {
88	      if (o.tipo === 'only') hallazgo('TEST-ONLY', `${f}:${o.linea}`, `${o.texto} — excluye al resto de la suite.`);
89	      else if (!(base.omisiones[f] || []).includes(o.texto)) hallazgo('OMISION-NUEVA', `${f}:${o.linea}`, `${o.texto} — omisión no aprobada.`);
90	    }
91	    for (const p of a.pruebas) {
92	      const donde = `${f}:${p.linea} «${p.titulo}»`;
93	      if (p.asserts === 0) hallazgo('SIN-ASSERTS', donde, 'La prueba no tiene ningún expect(): no puede fallar por comportamiento.');
94	      if (p.triviales.length) hallazgo('ASSERT-TRIVIAL', donde, `Afirma sobre un literal: ${p.triviales.join(' ; ')}`);
95	      if (p.sinAwait.length) hallazgo('ASSERT-SIN-AWAIT', donde, `Aserción asíncrona sin await (${p.sinAwait.join(', ')}): nunca hace fallar la prueba.`);
96	      if (p.tragaErrores) hallazgo('ERROR-TRAGADO', donde, 'Un .catch/try vacío puede convertir un fallo en éxito.');
97	      if (p.mockRed) hallazgo('RED-SIMULADA', donde, 'page.route/route.fulfill: la prueba verificaría una respuesta inventada, no Moodle.');
98	      if (p.modificador && !base.pruebas[idPrueba(p)]) hallazgo('OMITIDA', donde, `test.${p.modificador}() en prueba nueva.`);
99	    }
100	  }
101	
102	  // 3) Configuración global de la suite.
103	  const u0 = base.umbralVisual, u1 = actual.umbralVisual;
104	  if (u1.threshold > u0.threshold || u1.maxDiffPixelRatio > u0.maxDiffPixelRatio) hallazgo('UMBRAL-RELAJADO', CONFIG, `threshold ${u0.threshold}->${u1.threshold}, maxDiffPixelRatio ${u0.maxDiffPixelRatio}->${u1.maxDiffPixelRatio}`);
105	  if (u1.retries > u0.retries) hallazgo('REINTENTOS', CONFIG, `retries ${u0.retries}->${u1.retries}: los reintentos esconden pruebas inestables.`);
106	
107	  // 4) Líneas base visuales: toda imagen debe coincidir con una aprobación firmada.
108	  const aprobRef = json(enRef(APROBACIONES), {});
109	  const aprobAct = json(fs.existsSync(path.join(RAIZ, APROBACIONES)) ? fs.readFileSync(path.join(RAIZ, APROBACIONES), 'utf8') : null, {});
110	  const dirLB = path.join(RAIZ, 'visual/lineas-base');
111	  for (const png of fs.existsSync(dirLB) ? fs.readdirSync(dirLB).filter((f) => f.endsWith('.png')) : []) {
112	    const h = sha(path.join(dirLB, png));
113	    const aR = aprobRef[png], aA = aprobAct[png];
114	    if (aR && aR.sha256 === h) continue; // idéntica a la aprobada en main
115	    if (aR && aR.sha256 !== h) {
116	      // Cambió una línea base existente. Dos únicos caminos legítimos:
117	      //  a) aprobación humana nueva (origen humano, razón, hash exacto);
118	      //  b) DENTRO del pipeline de un spec que DECLARÓ esa pantalla como afectada: queda "propuesta-cambio",
119	      //     visible en el PR con su diferencia, y requiere aprobación humana antes de mergear.
120	      const humano = aA && aA.sha256 === h && aA.razon && aA.origen === 'humano';
121	      const propuestaDeclarada = plan && aA && aA.sha256 === h && aA.origen === 'pipeline' && aA.estado === 'propuesta-cambio'
122	        && (plan.pantallas_afectadas || []).some((s) => png.startsWith(s));
123	      if (!humano && !propuestaDeclarada) hallazgo('LINEA-BASE-ALTERADA', `visual/lineas-base/${png}`, `El hash cambió (${aR.sha256.slice(0, 12)} -> ${h.slice(0, 12)}) sin aprobación humana con razón${plan ? ` y sin que el spec ${plan.spec_id} declare esta pantalla como afectada` : ''}. Actualizar una línea base para que una prueba pase es la forma más barata de tapar una rotura.`);
124	      continue;
125	    }
126	    // Línea base nueva (pantalla nueva): la crea el pipeline y queda PENDIENTE de aprobación humana en el PR.
127	    if (!aA || aA.sha256 !== h) hallazgo('LINEA-BASE-SIN-REGISTRO', `visual/lineas-base/${png}`, 'Imagen nueva sin entrada en APROBACIONES.json.');
128	    else if (!plan && aA.origen !== 'humano') hallazgo('LINEA-BASE-SIN-APROBAR', `visual/lineas-base/${png}`, `Registrada por el pipeline (${aA.spec}) pero todavía sin aprobación humana.`);
129	  }
130	  for (const [png, a] of Object.entries(aprobRef)) if (!fs.existsSync(path.join(dirLB, png))) hallazgo('LINEA-BASE-ELIMINADA', `visual/lineas-base/${png}`, `Estaba aprobada (${a.razon}) y ya no existe.`);
131	
132	  // 5) Lo que se ejecutó: pruebas aprobadas que no corrieron, caminos de error que no se ejercitaron.
133	  if (resultados) {
134	    const corrio = new Map(resultados.map((r) => [`${r.archivo}::${r.titulo.split(' › ').pop()}`, r]));
135	    for (const [id, a] of Object.entries(actual.pruebas)) {
136	      const [archivo, titulo] = id.split('::');
137	      const r = [...corrio.entries()].find(([k]) => k.endsWith(`${path.basename(archivo)}::${titulo}`))?.[1];
138	      if (!r) continue; // no estaba en el alcance de esta corrida
139	      if ((a.tags || []).includes('@camino-error') && r.estado !== 'passed') hallazgo('CAMINO-ERROR-NO-EJERCITADO', id, `Estado: ${r.estado}. El camino de error debe ejecutarse y pasar.`);
140	    }
141	    for (const r of resultados) if (r.estado === 'skipped' && !r.anotaciones.some((x) => x.startsWith('skip:') && x.length > 8)) hallazgo('OMITIDA-EN-EJECUCION', `${r.archivo} «${r.titulo}» [${r.proyecto}]`, 'Se omitió sin razón declarada.');
142	  }
143	
144	  // 6) Prueba de mutación "sin la funcionalidad": las pruebas @requiere-feature deben FALLAR sin el plugin.
145	  if (sinFeature) {
146	    for (const r of sinFeature.filter((x) => /@requiere-feature/.test(x.titulo))) {
147	      if (r.estado === 'passed') hallazgo('PASA-SIN-FUNCIONALIDAD', `${r.archivo} «${r.titulo}» [${r.proyecto}]`, 'Pasa con el plugin desinstalado: no verifica lo que dice verificar.');
148	    }
149	  }
150	  return H;
151	}
152	
153	export function informe(H) {
